(()=>{'use strict';const BASE='https://woongbi-quote-api.woongbts.workers.dev',categories=['senior','value','premium'],rows={senior:[],value:[],premium:[]},state={ready:false,error:false};async function post(category){const ctl=typeof AbortController!=='undefined'?new AbortController():null,t=ctl?setTimeout(()=>ctl.abort(),8000):0;try{const response=await fetch(BASE+'/recommend/purpose',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({category,carrier:'all',join_type:'번호이동',basic_pension:false}),signal:ctl?.signal});const data=await response.json().catch(()=>({}));if(!response.ok||data?.ok!==true)throw Error(data?.error||('home-recommend-'+response.status));return(Array.isArray(data.items)?data.items:[]).map(item=>({...item,join:item.joinLabel||'번호이동'}))}finally{if(t)clearTimeout(t)}}function detailUrl(item){const q=new URLSearchParams();item?.d?.carrier&&q.set('c',item.d.carrier);q.set('j',item?.join||item?.joinLabel||'번호이동');if(['support','contract'].includes(item?.best?.method))q.set('m',item.best.method);item?.d?.id&&q.set('d',item.d.id);item?.p?.id&&q.set('p',item.p.id);q.set('mo','24');q.set('w',item?.welfare||'none');return'/rates.html?'+q.toString()}const ready=Promise.all(categories.map(async category=>{rows[category]=await post(category)})).then(()=>{state.ready=true;document.documentElement.dataset.homeRecommendApi='ready';return rows}).catch(error=>{state.error=true;document.documentElement.dataset.homeRecommendApi='unavailable';throw error});window.WoongbiRecommendationV2={ready,status:()=>({ready:state.ready,error:state.error,source:'server'}),recommend:category=>rows[category]||[],detailUrl,dataDate:()=> '서버 최신값'};})();
